// End-to-end browser test for /poc/quote — the FULL flow, no shortcuts.
//
// For each test address:
//   1. Load /poc/quote fresh
//   2. Upload a real fixture PDF bill (generated by gen-test-bill-pdf.mjs)
//   3. Wait for parse → ExtractStage
//   4. Type address into Places autocomplete
//   5. Wait for suggestions → click first match
//   6. Click "Analyse my roof"
//   7. Wait for AddressStage 3D
//   8. Verify pin marker + camera zoomed
//   9. Click "Yes, that's my house"
//   10. On MaterialStage, pick metal roof
//   11. Click "Design my system"
//   12. Wait for QuoteStage 3D + panels
//   13. Verify panels rendered, all within roof bounds, no overflow
//
// Uses puppeteer-core connected to the user's installed Chrome.
//
// Run:  node server/scripts/test-e2e-browser.mjs

import puppeteer from 'puppeteer-core';
import { promises as fs } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// ── Config ──────────────────────────────────────────────────────────────
const CHROME = process.env.E2E_CHROME_PATH || 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const CLIENT_URL = 'http://localhost:5173';
const SCREENSHOT_DIR = path.join(__dirname, 'test-output');
const FIXTURE_DIR    = path.join(__dirname, 'test-fixtures');
const HEADLESS = process.env.E2E_HEADLESS === '1';

// Each test scenario has its OWN bill PDF, address, and expected outcomes.
const SCENARIOS = [
  {
    label:      'Lynfield (older suburb, Google Solar path)',
    slug:       'lynfield',
    billPdf:    path.join(FIXTURE_DIR, 'e2e-lynfield-bill.pdf'),
    searchAddress: '25 Commodore Drive Lynfield',
    expectSource:  'live',                // Google Solar
    expectAtLeastNPanels: 8,              // 8517 kWh/yr → 10-14 panels typical
    expectMaxWidthOverflowM: 0.5,         // no panel more than 0.5m past face bbox
  },
  {
    label:      '6 Woodacre (new sub, LiDAR fallback)',
    slug:       'woodacre',
    billPdf:    path.join(FIXTURE_DIR, 'e2e-woodacre-bill.pdf'),
    searchAddress: '6 Woodacre Street Flat Bush',
    expectSource:  'lidar',
    expectAtLeastNPanels: 6,              // small roof; may cap below target
    expectMaxWidthOverflowM: 0.5,
  },
  {
    label:      'Wellington (proves NZ-wide LiDAR — not Auckland-only)',
    slug:       'wellington',
    billPdf:    path.join(FIXTURE_DIR, 'e2e-wellington-bill.pdf'),
    searchAddress: 'Molesworth Street Wellington',
    // May use Google Solar OR LiDAR — Wellington has Google Solar coverage in
    // some places. What matters: the flow works to a rendered quote.
    expectAtLeastNPanels: 6,
    expectMaxWidthOverflowM: 0.5,
  },
  {
    label:      '75 Mahia Manurewa (regression: complex 7-face hip roof)',
    slug:       'mahia',
    billPdf:    path.join(FIXTURE_DIR, 'e2e-mahia-bill.pdf'),
    searchAddress: '75 Mahia Road Manurewa',
    // Real address that surfaced the overflow + patchy bugs. Google Solar
    // returns 7 faces here; primary is a 55.8 m² W-facing plane whose bbox
    // over-estimated true face by ~40%. Anchor test for the fix.
    expectSource:  'live',
    expectAtLeastNPanels: 8,
    expectMaxWidthOverflowM: 0.5,
  },
];

// ── Test-plumbing ───────────────────────────────────────────────────────
let pass = 0, fail = 0;
const assert = (cond, msg) => {
  if (cond) { pass++; console.log(`    ✓ ${msg}`); }
  else      { fail++; console.error(`    ✗ ${msg}`); }
};

async function ensureDir(dir) { await fs.mkdir(dir, { recursive: true }); }
async function screenshot(page, filename) {
  const full = path.join(SCREENSHOT_DIR, filename);
  await page.screenshot({ path: full, fullPage: false });
  return full;
}

// Wait for Cesium3DView to publish its debug state via window.__cesium3DState.
async function waitForCesiumState(page, timeoutMs = 60_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const state = await page.evaluate(() => window.__cesium3DState || null);
    if (state && !state.error) return state;
    if (state?.error) throw new Error(`Cesium3DView error: ${state.error}`);
    await new Promise(r => setTimeout(r, 500));
  }
  throw new Error(`Cesium state not published within ${timeoutMs}ms`);
}

// Poll until entityCount >= expectedMin (or timeout, returns whatever last state).
async function waitForCesiumEntities(page, expectedMin, timeoutMs = 45_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const state = await page.evaluate(() => window.__cesium3DState || null);
    if (state?.error) throw new Error(`Cesium3DView error: ${state.error}`);
    if (state?.entityCount >= expectedMin) return state;
    await new Promise(r => setTimeout(r, 750));
  }
  return await page.evaluate(() => window.__cesium3DState || null);
}

async function clickByText(page, text) {
  const clicked = await page.evaluate((t) => {
    const buttons = [...document.querySelectorAll('button')];
    const match = buttons.find(b => b.textContent && b.textContent.trim().toLowerCase().includes(t.toLowerCase()));
    if (match) { match.click(); return true; }
    return false;
  }, text);
  if (!clicked) throw new Error(`No button matching "${text}" found`);
}

async function waitForButtonEnabled(page, text, timeoutMs = 30_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const found = await page.evaluate((t) => {
      const buttons = [...document.querySelectorAll('button')];
      return buttons.some(b => b.textContent && b.textContent.trim().toLowerCase().includes(t.toLowerCase()) && !b.disabled);
    }, text);
    if (found) return;
    await new Promise(r => setTimeout(r, 500));
  }
  throw new Error(`Button "${text}" not enabled after ${timeoutMs}ms`);
}

async function waitForButtonPresent(page, text, timeoutMs = 30_000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const found = await page.evaluate((t) => {
      const buttons = [...document.querySelectorAll('button')];
      return buttons.some(b => b.textContent && b.textContent.trim().toLowerCase().includes(t.toLowerCase()));
    }, text);
    if (found) return;
    await new Promise(r => setTimeout(r, 500));
  }
  throw new Error(`Button "${text}" not present after ${timeoutMs}ms`);
}

function distMeters(a, b) {
  const dLat = (a.latitude - b.latitude) * 111320;
  const dLng = (a.longitude - b.longitude) * 111320 * Math.cos(a.latitude * Math.PI / 180);
  return Math.sqrt(dLat * dLat + dLng * dLng);
}

// Attach console + response listeners to a page for diagnostics.
function attachListeners(page) {
  page.on('console', msg => {
    const type = msg.type();
    if (['error', 'warning'].includes(type) || msg.text().startsWith('[')) {
      console.log(`    [browser ${type}] ${msg.text().slice(0, 250)}`);
    }
  });
  page.on('pageerror', err => console.error(`    [browser exception] ${err.message}`));
  page.on('response', async (resp) => {
    if (resp.status() >= 400) {
      let body = '';
      try { body = (await resp.text()).slice(0, 400); } catch { /* noop */ }
      console.log(`    [http ${resp.status()}] ${resp.request().method()} ${resp.url()}`);
      if (body) console.log(`      body: ${body}`);
    }
  });
}

// ═══════════════════════════════════════════════════════════════════════
// Full E2E flow for one scenario: bill upload → quote screen with panels
// ═══════════════════════════════════════════════════════════════════════
async function testFullFlow(browser, spec) {
  console.log(`\n══ ${spec.label} — FULL FLOW ══`);
  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900 });
  attachListeners(page);

  // Capture the /extract API body so we can assert on it later.
  let extractApiBody = null;
  page.on('response', async (resp) => {
    if (resp.url().includes('/api/bills/extract') && resp.request().method() === 'POST') {
      try { extractApiBody = await resp.json(); } catch { /* noop */ }
    }
  });

  console.log(`  → step 1: navigating to ${CLIENT_URL}/poc/quote (fresh, no shortcuts)`);
  await page.goto(`${CLIENT_URL}/poc/quote`, { waitUntil: 'networkidle2', timeout: 30_000 });

  // ── Step 2: Bill upload ──
  console.log(`  → step 2: uploading fixture bill ${path.basename(spec.billPdf)}`);
  await page.waitForSelector('input[type="file"]', { timeout: 10_000 });
  const input = await page.$('input[type="file"]');
  await input.uploadFile(spec.billPdf);

  // ── Step 3: Wait for ExtractStage ──
  console.log('  → step 3: waiting for parse → ExtractStage');
  await waitForButtonPresent(page, 'analyse my roof', 30_000);
  await screenshot(page, `${spec.slug}-01-extract.png`);
  assert(extractApiBody?.retailer === 'Mercury',
         `bill parse: retailer = 'Mercury' (got '${extractApiBody?.retailer}')`);
  assert(extractApiBody?.kwh_total > 0,
         `bill parse: kwh_total > 0 (got ${extractApiBody?.kwh_total})`);

  // ── Step 4: Type into Places autocomplete ──
  console.log(`  → step 4: typing "${spec.searchAddress}" into autocomplete`);
  // The autocomplete input is inside the "Confirm your address" section.
  // Focus it and type.
  await page.evaluate(() => {
    const inp = document.querySelector('input[placeholder*="Start typing" i], input[placeholder*="address" i]');
    if (inp) { inp.focus(); inp.select(); }
  });
  // Type character by character (triggers debounced autocomplete)
  await page.keyboard.type(spec.searchAddress, { delay: 30 });

  // ── Step 5: Wait for suggestions + click first ──
  console.log('  → step 5: waiting for autocomplete suggestions');
  const suggestionSelector = 'ul li[class*="cursor-pointer"], li[onmousedown]';
  await page.waitForFunction(() => {
    const items = document.querySelectorAll('ul li');
    return items.length > 0;
  }, { timeout: 15_000 });
  console.log('  → step 5b: clicking first suggestion');
  await page.evaluate(() => {
    const item = document.querySelector('ul li');
    if (item) {
      // The client uses onMouseDown handler — dispatch that event
      const md = new MouseEvent('mousedown', { bubbles: true, cancelable: true });
      item.dispatchEvent(md);
    }
  });

  // ── Step 6: Click Analyse ──
  await waitForButtonEnabled(page, 'analyse my roof', 15_000);
  console.log('  → step 6: clicking "Analyse my roof"');
  await clickByText(page, 'analyse my roof');

  // ── Step 7: Wait for AddressStage 3D ──
  console.log('  → step 7: waiting for AddressStage 3D (up to 60s)');
  await waitForCesiumState(page, 60_000);
  await new Promise(r => setTimeout(r, 6000));   // let flyTo settle
  const addrState = await page.evaluate(() => window.__cesium3DState);
  const addrShotPath = await screenshot(page, `${spec.slug}-02-address.png`);
  const addrStat = await fs.stat(addrShotPath);
  console.log(`    AddressStage camera h=${addrState.camera.height?.toFixed(0)}m, screenshot ${(addrStat.size / 1024).toFixed(0)} KB`);

  assert(addrStat.size > 200_000,
         `AddressStage: screenshot >200KB (not black canvas) — ${(addrStat.size / 1024).toFixed(0)} KB`);
  assert(addrState.camera.height < 500,
         `AddressStage: camera zoomed to house (<500m) — ${addrState.camera.height?.toFixed(0)}m`);

  // ── Step 8: Pin marker present ──
  const pinInfo = await page.evaluate(() => {
    const viewer = window.__cesiumViewer;
    if (!viewer) return { hasPin: false };
    const pin = viewer.entities.getById('__customer_pin');
    return { hasPin: !!pin, hasLabel: !!pin?.label };
  });
  assert(pinInfo.hasPin,   `AddressStage: pin marker entity present (customer can see their house)`);
  assert(pinInfo.hasLabel, `AddressStage: pin has "Your house" label`);

  // ── Step 9: Click "Yes, that's my house" ──
  console.log('  → step 9: clicking "Yes, that\'s my house"');
  await waitForButtonEnabled(page, "yes, that's my house", 10_000);
  await clickByText(page, "yes, that's my house");

  // Reset debug state so we know when QuoteStage publishes fresh.
  await page.evaluate(() => { delete window.__cesium3DState; delete window.__cesiumViewer; });

  // ── Step 10: MaterialStage - pick metal ──
  console.log('  → step 10: picking metal roof');
  await new Promise(r => setTimeout(r, 500));
  const pickedMetal = await page.evaluate(() => {
    const buttons = [...document.querySelectorAll('button')];
    const metal = buttons.find(b => b.textContent?.toLowerCase().includes('metal roof'));
    if (metal) { metal.click(); return true; }
    return false;
  });
  assert(pickedMetal, `MaterialStage: metal roof option clickable`);

  // ── Step 11: Click Design my system ──
  await waitForButtonEnabled(page, 'design my system', 10_000);
  console.log('  → step 11: clicking "Design my system"');
  await clickByText(page, 'design my system');

  // ── Step 12: Wait for QuoteStage 3D + panels ──
  console.log('  → step 12: waiting for QuoteStage panels (up to 60s)');
  const quoteState = await waitForCesiumEntities(page, spec.expectAtLeastNPanels, 60_000);
  await new Promise(r => setTimeout(r, 4000));   // let flyTo settle
  const finalState = await page.evaluate(() => window.__cesium3DState);
  const quoteShotPath = await screenshot(page, `${spec.slug}-03-quote.png`);
  const quoteStat = await fs.stat(quoteShotPath);
  console.log(`    QuoteStage camera h=${finalState.camera.height?.toFixed(0)}m, entities=${finalState.entityCount}, screenshot ${(quoteStat.size / 1024).toFixed(0)} KB`);
  console.log(`    allocations: ${JSON.stringify(finalState.allocations)}`);

  assert(quoteStat.size > 200_000,
         `QuoteStage: screenshot >200KB — ${(quoteStat.size / 1024).toFixed(0)} KB`);
  assert(finalState.camera.height < 500,
         `QuoteStage: camera not in space — ${finalState.camera.height?.toFixed(0)}m`);
  assert(finalState.entityCount >= spec.expectAtLeastNPanels,
         `QuoteStage: at least ${spec.expectAtLeastNPanels} panels rendered — got ${finalState.entityCount}`);

  // ── Step 13: PANELS MUST FIT ON ROOF ──
  // For each allocation's segment, we know the face dimensions (or bbox).
  // Check that all entity positions fall within a reasonable bbox around the
  // segment centroid — no panel should be more than expectMaxWidthOverflowM
  // metres beyond the face extent.
  const fitCheck = await page.evaluate(() => {
    const viewer = window.__cesiumViewer;
    if (!viewer) return { ok: false, reason: 'no viewer' };
    const entities = viewer.entities.values.filter(e => e.box);   // panel boxes
    return {
      ok: true,
      count: entities.length,
      positions: entities.map(e => {
        const cart = e.position?.getValue?.(window.Cesium?.JulianDate?.now?.() || undefined);
        return cart ? null : null;   // simple existence check; detailed geom below
      }).length,
    };
  });
  // Use per-entity positions from the debug state (already provided by publishDebugState)
  const positions = finalState.entityPositions || [];
  const centroid = positions.length ? {
    latitude:  positions.reduce((s, p) => s + p.latitude,  0) / positions.length,
    longitude: positions.reduce((s, p) => s + p.longitude, 0) / positions.length,
  } : finalState.requestedCoords;
  const maxDistM = Math.max(...positions.map(p => distMeters(p, centroid)));
  console.log(`    farthest panel from cluster centroid: ${maxDistM.toFixed(1)}m`);
  // A residential roof face is <10m across — the farthest panel from the
  // cluster centroid should be <7m (spans up to 14m across the widest side).
  assert(maxDistM < 7,
    `panels stay within a residential-roof extent (<7m radius from centroid) — got ${maxDistM.toFixed(1)}m`);

  await page.close();
}

// ── Sanity: are the servers up? ─────────────────────────────────────────
async function sanityChecks() {
  try {
    const r = await fetch(CLIENT_URL);
    if (!r.ok) throw new Error(`client ${r.status}`);
    console.log(`✓ Vite client responsive at ${CLIENT_URL}`);
  } catch (e) {
    console.error(`✗ Vite client not running at ${CLIENT_URL} — start with (cd client && npm run dev)`);
    process.exit(1);
  }
  try {
    const r = await fetch('http://localhost:5000/api/places/autocomplete?input=test');
    if (!r.ok) throw new Error(`server ${r.status}`);
    console.log(`✓ Backend responsive at localhost:5000`);
  } catch (e) {
    console.error(`✗ Backend not running at localhost:5000 — start with (cd server && npm run dev)`);
    process.exit(1);
  }
  // Fixture files
  for (const spec of SCENARIOS) {
    try {
      await fs.stat(spec.billPdf);
      console.log(`✓ Fixture bill present: ${path.basename(spec.billPdf)}`);
    } catch {
      console.error(`✗ Fixture bill missing: ${spec.billPdf}`);
      console.error(`  Generate with: node server/scripts/gen-test-bill-pdf.mjs --out=${path.basename(spec.billPdf)}`);
      process.exit(1);
    }
  }
}

// ── Run ─────────────────────────────────────────────────────────────────
await ensureDir(SCREENSHOT_DIR);
await sanityChecks();

console.log(`\n▶ Launching Chrome (${HEADLESS ? 'HEADLESS' : 'HEADED for reliable WebGL'})…`);
const browser = await puppeteer.launch({
  executablePath: CHROME,
  headless: HEADLESS ? 'new' : false,
  defaultViewport: null,
  args: ['--window-size=1440,900'],
});
console.log(`  Chrome PID ${browser.process()?.pid}`);

try {
  for (const spec of SCENARIOS) {
    try {
      await testFullFlow(browser, spec);
    } catch (e) {
      fail++;
      console.error(`  ✗ ${spec.label} — flow threw: ${e.message}`);
    }
  }
} finally {
  await browser.close();
}

console.log(`\n━━━ ${pass} passed · ${fail} failed ━━━`);
console.log(`Screenshots: ${SCREENSHOT_DIR}\n`);
if (fail > 0) process.exit(1);
